import{_ as o,o as t,c as a,a0 as s}from"./chunks/framework.ChlVJx0I.js";const p=JSON.parse('{"title":"background jobs extension","description":"","frontmatter":{},"headers":[],"relativePath":"extensions/background-jobs.md","filePath":"extensions/background-jobs.md","lastUpdated":1790113677000}'),n={name:"extensions/background-jobs.md"};function i(r,e,d,l,h,c){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="background-jobs-extension" tabindex="-1">background jobs extension <a class="header-anchor" href="#background-jobs-extension" aria-label="Permalink to &quot;background jobs extension&quot;">​</a></h1><p>Runs long commands in the background, so the agent is not blocked for the whole duration of a test suite, a build, or a long fetch. Three tools:</p><ul><li><code>bash_bg</code> starts a command detached and returns the job id, the pid, and the log path. The command runs through a shell; its stdout and stderr go to a per-job log file. Parameters: <code>command</code> (required), <code>cwd</code>, <code>env</code> (extra variables merged over the current environment), and <code>label</code>.</li><li><code>job_wait</code> blocks until the job exits or a timeout (default 120 seconds) and returns the exit code with a tail of the output (default 30 lines). On timeout it returns &quot;still running&quot; with the tail so far, so the agent can wait again or move on.</li><li><code>job_status</code> reports one job by id, or lists every job with its age, its label or command head, and its status, without waiting.</li></ul><p>The tools are active by default. The guideline is: background a command only when it is expected to take more than about ten seconds, or when other work can proceed while it runs; plain bash stays the default.</p><h2 id="tool-row" tabindex="-1">Tool row <a class="header-anchor" href="#tool-row" aria-label="Permalink to &quot;Tool row&quot;">​</a></h2><p>The <code>bash_bg</code> tool row - the TUI entry for the call in an agent turn - shows the command in the built-in bash line shape, <code>$ &lt;command&gt;</code>, with no background marker: the tool name already says the command is backgrounded, and the command line is the true intent (<a href="/pi-extensions/adr/0024-bash-bg-tool-row-shows-the-plain-command-line.html">ADR 0024</a>). A multi-line command renders in full, and while the arguments stream in the row shows <code>$ ...</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ npm test</span></span>
<span class="line"><span>job jb-abc123 started</span></span>
<span class="line"><span>pid: 4242</span></span>
<span class="line"><span>log: ~/.pi/agent/sessions/jobs/jb-abc123/job.log</span></span>
<span class="line"><span>wait on it with job_wait; inspect it with job_status.</span></span></code></pre></div><h2 id="job-state" tabindex="-1">Job state <a class="header-anchor" href="#job-state" aria-label="Permalink to &quot;Job state&quot;">​</a></h2><p>Job state lives on disk, one directory per job under pi&#39;s agent state root (the parent of the session directory), in a <code>jobs</code> subdirectory. Each directory holds the manifest (command, cwd, label, pid, start time, log path), the command script, the log, the child pid, and the exit code. Jobs outlive the session that started them: a new session can list and wait on a job an old session started. <code>PI_JOBS_DIR</code> overrides the root. (<a href="/pi-extensions/adr/0023-background-jobs-keep-state-on-disk-per-job.html">ADR 0023</a>.)</p><ul><li><strong>The exit code is recorded by a shell wrapper.</strong> The wrapper runs the command with its output to the log, records the child pid, and writes the exit code to a file on exit, so the code is knowable to any process, not only the one that spawned the command.</li><li><strong>A machine-level bound of eight</strong> concurrent running jobs. A start beyond the bound is refused with the list of running jobs.</li><li><strong>Stale cleanup.</strong> Starting a new job removes job directories older than seven days, so the state directory does not grow forever.</li><li><strong>No kill tool.</strong> To stop a job, signal the pid that <code>job_status</code> reports through the ordinary bash tool. A dedicated kill is a candidate if sessions show the need.</li></ul><p>POSIX only: the wrapper is <code>/bin/sh</code>. The extension set targets the operator&#39;s Linux and macOS machines.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>The spawn, poll, tail, cleanup, and formatting logic lives in the core module (<code>extensions/background-jobs/core.ts</code>); the pi wiring (<code>index.ts</code>) only registers the three tools and resolves the job root from the session file.</p>`,13)])])}const u=o(n,[["render",i]]);export{p as __pageData,u as default};
